        {"action": "rollback_service", "params": {"service": "payment-service"}},
        {"action": "replay_payment_confirmations", "params": {}}
      ]
    },
    {
      "service": "invoice-agent",
      "kind": "bad_deploy",
      "mechanism": "Deploy of invoice-agent v1.2 at t=553 introduced incorrect VAT or total calculations in invoices, which sync-job then copied to the ledger, violating I3_ledger_integrity.",
      "supporting": ["E2", "E6", "E18"],
      "refuting": ["E16"],
      "explains": ["I3_ledger_integrity"],
      "repair_plan": [
        {"action": "rollback_service", "params": {"service": "invoice-agent"}},
        {"action": "resync_ledger", "params": {}}
      ]
    }
  ],
  "summary": "Two independent bad deploys: payment-service v2.0 causing unconfirmed order payments, and invoice-agent v1.2 causing incorrect VAT calculations."
}
